CREATE TABLE IF NOT EXISTS "proxy_pool" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "url" TEXT NOT NULL, "is_default" BOOLEAN DEFAULT false, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'));
ALTER TABLE "sites" ADD COLUMN "proxy_id" INTEGER;
CREATE INDEX "proxy_pool_default_idx" ON "proxy_pool" ("is_default");
